<?php $pageTitle='Batch-wise curriculum';$programmeFilter=(string)($_GET['programme']??'');$batchFilter=(int)($_GET['batch_id']??0);$semesterFilter=(int)($_GET['semester']??0); ?>
<section class="page-heading"><div><p class="eyebrow">Academic masters</p><h1>Batch-wise course structure</h1><p>Assign each subject to the exact programme batch and semester that studies it.</p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('courses/import/template.csv')) ?>">Download template</a><a class="primary-button" href="<?= e(url('courses/import')) ?>">Bulk import course structure</a></div></section>
<?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<div class="context-note" role="note"><i class="ti ti-info-circle" aria-hidden="true"></i><p><strong>Batch-specific curriculum</strong><span>Each mapping belongs to one batch, such as UCS 2023-2027. Removing it does not remove the same subject from another batch.</span></p></div>
<section class="curriculum-stats"><div><span>Batch-course mappings</span><strong><?= number_format(count($courses)) ?></strong></div><div><span>Batches represented</span><strong><?= number_format(count(array_unique(array_filter(array_column($courses,'batch_id'))))) ?></strong></div><div><span>Subject codes</span><strong><?= number_format(count(array_unique(array_column($courses,'id')))) ?></strong></div></section>
<section class="split-workspace curriculum-workspace"><form class="panel quick-form" method="post" action="<?= e(url('courses')) ?>"><?= csrf_field() ?><p class="eyebrow">Batch curriculum</p><h2>Add or update course</h2>
<div class="quick-form-scroll" tabindex="0" aria-label="Course details"><label>Programme / branch<select name="programme_id" id="course-programme" required><option value="">Select programme</option><?php foreach($programmes as $programme):?><option value="<?= (int)$programme['id'] ?>"><?= e($programme['code'].' - '.$programme['name']) ?></option><?php endforeach;?></select></label>
<label>Academic batch<select name="batch_id" id="course-batch" required disabled><option value="">Select programme first</option><?php foreach($batches as $batch):?><option value="<?= (int)$batch['id'] ?>" data-programme="<?= (int)$batch['programme_id'] ?>"><?= e($batch['label']) ?></option><?php endforeach;?></select><small>Subjects are isolated by admission batch.</small></label>
<div class="course-form-pair"><label>Course level<select name="course_level" required><option value="UG">UG</option><option value="PG">PG</option></select></label><label>Course year<select name="course_year" required><?php for($i=1;$i<=6;$i++):?><option value="<?= $i ?>">Year <?= $i ?></option><?php endfor;?></select></label></div>
<div class="course-form-pair"><label>Semester<select name="semester" required><option value="">Select semester</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>">Semester <?= $i ?></option><?php endfor;?></select></label><label>Section<input name="section" value="ALL" maxlength="20" pattern="[A-Za-z0-9-]+" required><small>Use ALL for the complete batch.</small></label></div><label>Course code<input name="code" placeholder="CS-101" maxlength="40" required></label><label>Course name<input name="name" placeholder="Programming Fundamentals" required></label>
<div class="course-form-pair"><label>Course credits<input name="course_credits" type="number" min="0" max="99.9" step="0.5" value="4" required></label><label>Category<select name="category"><option value="core">Core</option><option value="elective">Elective</option><option value="common">Common</option><option value="bridge">Bridge</option><option value="back_paper">Back paper</option><option value="other">Other</option></select></label></div>
<div class="course-form-pair"><label>Mid-sem exam hours<input name="mid_sem_hours" type="number" min="0.5" max="6" step="0.5" value="1.5" required></label><label>End-sem exam hours<input name="end_sem_hours" type="number" min="0.5" max="8" step="0.5" value="3" required></label></div><label>Scheduling priority<input name="subject_priority" type="number" min="1" max="100" value="50" required><small>1 is scheduled earliest; 100 is lowest priority.</small></label></div><footer class="quick-form-footer"><span><i class="ti ti-device-floppy" aria-hidden="true"></i> Course details are saved to the selected batch.</span><button class="primary-button"><i class="ti ti-device-floppy" aria-hidden="true"></i> Save batch course</button></footer></form>
<section class="panel table-panel curriculum-register"><form class="table-toolbar curriculum-filters" method="get"><div class="toolbar-title"><strong>Course structure register</strong><span>Filter the curriculum by programme, batch, and semester.</span></div><label><span>Programme</span><select name="programme"><option value="">All programmes</option><?php foreach($programmes as $programme):?><option value="<?= e($programme['code']) ?>" <?= $programmeFilter===$programme['code']?'selected':'' ?>><?= e($programme['code']) ?></option><?php endforeach;?></select></label><label><span>Batch</span><select name="batch_id"><option value="0">All batches</option><?php foreach($batches as $batch):?><option value="<?= (int)$batch['id'] ?>" <?= $batchFilter===(int)$batch['id']?'selected':'' ?>><?= e($batch['label']) ?></option><?php endforeach;?></select></label><label><span>Semester</span><select name="semester"><option value="0">All semesters</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>" <?= $semesterFilter===$i?'selected':'' ?>>Semester <?= $i ?></option><?php endfor;?></select></label><div class="toolbar-actions"><button class="secondary-button"><i class="ti ti-filter" aria-hidden="true"></i> Apply filters</button><?php if($programmeFilter!==''||$batchFilter||$semesterFilter):?><a class="text-button" href="<?= e(url('courses')) ?>">Clear</a><?php endif;?></div></form>
<div class="table-scroll"><table><thead><tr><th>Programme / batch</th><th>Course</th><th>Level / year</th><th>Semester / section</th><th>Credits</th><th>Exam duration</th><th>Category</th><th>Priority</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php $shown=0;foreach($courses as $course):if(($programmeFilter!==''&&$course['programme_code']!==$programmeFilter)||($batchFilter&&$batchFilter!==(int)$course['batch_id'])||($semesterFilter&&$semesterFilter!==(int)$course['semester']))continue;$shown++;?><tr><td><strong><?= e($course['programme_code']) ?></strong><small class="cell-note"><?= e($course['batch_label']?:'Legacy / unassigned batch') ?></small></td><td><strong><?= e($course['code']) ?></strong><small class="cell-note"><?= e($course['name']) ?></small></td><td><strong><?= e($course['course_level']) ?></strong><small class="cell-note">Year <?= (int)$course['course_year'] ?></small></td><td><span class="semester-chip">Semester <?= (int)$course['semester'] ?></span><small class="cell-note">Section <?= e($course['section']) ?></small></td><td><?= e(number_format((float)$course['course_credits'],1)) ?></td><td><strong>Mid: <?= e(number_format((int)$course['mid_sem_duration_minutes']/60,1)) ?> h</strong><small class="cell-note">End: <?= e(number_format((int)$course['end_sem_duration_minutes']/60,1)) ?> h</small></td><td><?= e(ucwords(str_replace('_',' ',$course['category']))) ?></td><td><span class="priority-chip"><?= (int)$course['subject_priority'] ?></span></td><td><span class="status-label <?= e($course['status']) ?>"><?= e(ucfirst($course['status'])) ?></span></td><td><form method="post" action="<?= e(url('courses/curriculum/'.(int)$course['mapping_id'].'/delete')) ?>" data-confirm="<?= e('Remove '.$course['code'].' from '.($course['batch_label']?:$course['programme_code']).' Semester '.$course['semester'].' Section '.$course['section'].'?') ?>" onsubmit="return window.confirm(this.dataset.confirm)"><?= csrf_field() ?><button class="secondary-button" type="submit"><i class="ti ti-trash" aria-hidden="true"></i> Delete</button></form></td></tr><?php endforeach;?><?php if(!$shown):?><tr><td colspan="10" class="empty-table-cell">No courses match this batch and semester.</td></tr><?php endif;?></tbody></table></div></section></section>
<script>(()=>{const programme=document.getElementById('course-programme'),batch=document.getElementById('course-batch'),source=[...batch.options].slice(1).map(o=>o.cloneNode(true));function sync(){const previous=batch.value;batch.innerHTML='<option value="">Select academic batch</option>';source.filter(o=>o.dataset.programme===programme.value).forEach(o=>batch.append(o.cloneNode(true)));batch.disabled=!programme.value||batch.options.length===1;if([...batch.options].some(o=>o.value===previous))batch.value=previous;}programme.addEventListener('change',sync);sync();})();</script>
